import { useEffect, useState } from "react";
import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { Box } from "@/shared/ui/layout/Box";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { STUDIO_INIT_CMD } from "@/features/studio-sessions/lib/studioSessions";
import { seedStudioLaunchState, studioStartPrompt } from "@/features/studio-sessions/StudioSessionMount";

/** The persona every network architect runs as — the same identity the Teams Studio architect carries.
 *  A network changes WHICH domain the architect is pointed at, not what an architect IS. */
export const NETWORK_ARCHITECT_PERSONA = "persona-architect";

/** The pane id for a network's architect: `network-<slug>:architect`.
 *
 *  `networkId` is already `network-<slug>` — the id the `bsc network` store mints — so the pane KEY is
 *  the network id and the two cannot drift. One colon, per the pane grammar: the key is read as
 *  `paneId.split(":")[0]`, so a compound key takes a hyphen and never a second colon.
 *
 *  This must agree byte-for-byte with `bsc_session::network_architect_slug` on the Rust side, which is
 *  what decides whether `bsc session stop <id>` may name it. `networkArchitectPane.test.ts` pins the
 *  two against each other. */
export function networkArchitectPaneId(networkId: string): string {
  return `${networkId}:architect`;
}

/** Keep ONE network's architect session warm.
 *
 *  A sibling of `StudioSessionMount` rather than a variant of it: that component is keyed on `StudioId`,
 *  a compile-time literal union, and a network is created by the user at runtime. What the two share is
 *  the LAUNCH PATH — `seedStudioLaunchState` and `STUDIO_INIT_CMD` — because a second way to start a
 *  session is a second way for it to be wrong. Only the identity differs, and identity is data.
 *
 *  The session's context is its persona prompt alone. A studio also appends a SCOPE directive
 *  (`studioScopeDirective`) naming the technology it may curate, which has no analogue here: a network
 *  is not a partition of a store, it is a set of projects, and the architect's charter already says what
 *  an architect does. Which network it belongs to is carried by the workspace it runs in.
 */
export function NetworkArchitectMount({ networkId }: { networkId: string }) {
  // undefined = still resolving; null = setup failed (no session); string = the workspace cwd.
  const [cwd, setCwd] = useState<string | null | undefined>(undefined);
  const paneId = networkArchitectPaneId(networkId);

  useEffect(() => {
    let alive = true;
    void (async () => {
      // The PANE ID is what crosses, not a bare slug: Rust derives the directory from it only after it
      // passes the same grammar `bsc session` resolves against, so there is one validator rather than a
      // frontend copy that can drift from it.
      const paths = await safeInvoke<Record<string, string> | null>(
        "setup_network_architect_workspace",
        { paneId, context: studioStartPrompt(NETWORK_ARCHITECT_PERSONA) },
        null,
        (e: unknown) => console.error(`${paneId} workspace setup failed:`, e),
      );
      if (!alive) return;
      const dir = paths?.network_dir;
      if (!dir) { setCwd(null); return; }
      seedStudioLaunchState({
        paneId,
        role: "architect",
        personaId: NETWORK_ARCHITECT_PERSONA,
        // No curated default skills: an architect runs discovery and hands off, and the skills a
        // project needs are the director's to attach once it exists.
        defaultSkillIds: [],
      });
      useAppStore.getState().registerTunnelPanes(paneId, [{
        id: paneId, cwd: dir, name: `${networkId} architect`, status: "running", kind: "architect",
      }]);
      setCwd(dir);
    })();
    return () => { alive = false; useAppStore.getState().registerTunnelPanes(paneId, []); };
  }, [networkId, paneId]);

  if (!cwd) return null;
  return (
    // Off-screen (NOT display:none, so the parked xterm still fits to a real size) permanent `primary`
    // claim, exactly as a studio mount does. A visible viewer — the Glance morph — re-parents the
    // terminal out of here when it opens.
    <Box
      aria-hidden
      data-testid={`network-architect-mount-${networkId}`}
      style={{
        position: "absolute", left: -99999, top: 0, width: 800, height: 600,
        overflow: "hidden", pointerEvents: "none", display: "flex", flexDirection: "column",
      }}
    >
      {/* `parked`: this claim resolves async and must never take ownership from a visible morph that
          claimed first — it owns the terminal only when it is the last claim standing. */}
      <TerminalSlot paneId={paneId} primary parked visible={false} initialCwd={cwd} initCmd={STUDIO_INIT_CMD} />
    </Box>
  );
}
